struct Session {
  int id;
  ~Session() { std::cout << "~Session\n"; }
};
int main() {
  Session* raw = new Session{1};
  std::shared_ptr<Session> owner(raw);
  std::shared_ptr<Session> observer(raw);
  std::cout << owner.use_count() << ' '
            << observer.use_count() << '\n';
}

int main() {
  auto owner = std::make_shared<Session>(1);
  std::shared_ptr<Session> observer = owner;
  std::cout << owner.use_count() << ' '
            << observer.use_count() << '\n';
}   // 2 2, then ~Session once

