std::shared_ptr<FILE> open_cfg(const char* p) {
  FILE* raw = std::fopen(p, "r");
  if (!raw) return nullptr;  // no block
  return std::shared_ptr<FILE>(
      raw, [](FILE* f) { std::fclose(f); });
}
// now prints: 0 0

