// Before C++17 this could leak:
// new A, then g() throws, before
// the shared_ptr owns the A.
f(std::shared_ptr<A>(new A), g());

// No naked new, nothing to leak:
f(std::make_shared<A>(), g());

struct Node {
  std::shared_ptr<Node> next;
};
int main() {
  auto head = std::make_shared<Node>();
  auto cur = head;
  for (int i = 0; i < 1'000'000; ++i)
    cur = cur->next = std::make_shared<Node>();
  cur.reset();
  head.reset();  // ?
  std::cout << "done\n";
}

void destroy(std::shared_ptr<Node> head) {
  while (head)
    head = std::move(head->next);
}
